--
-- Table structure for table `oderslist`
--

DROP TABLE IF EXISTS `oderslist`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `oderslist` (
  `_id` int NOT NULL AUTO_INCREMENT,
  `date` date DEFAULT NULL,
  `idDriver` int DEFAULT NULL,
  `idCustomer` int DEFAULT NULL,
  `idLoadingPoint` json DEFAULT NULL,
  `idUnloadingPoint` json DEFAULT NULL,
  `customerPrice` decimal(8,2) DEFAULT NULL,
  `driverPrice` decimal(8,2) DEFAULT NULL,
  `proxy` tinyint NOT NULL DEFAULT '1',
  `completed` tinyint NOT NULL DEFAULT '1',
  `document` enum('Ок','Нет','Факс','Сдал') NOT NULL DEFAULT 'Нет',
  `dateOfSubmission` datetime DEFAULT NULL,
  `customerPayment` enum('Ок','Нет','Мыло','Печать','Почта','Обещал оплату','Отдал клиенту','Частично оплачен') NOT NULL DEFAULT 'Нет',
  `dateOfPromise` datetime DEFAULT NULL,
  `driverPayment` enum('Ок','нет') NOT NULL DEFAULT 'нет',
  `dateOfPayment` datetime DEFAULT NULL,
  `accountNumber` varchar(7) DEFAULT NULL,
  `partialPaymentAmount` decimal(8,2) DEFAULT NULL,
  `idTrackDriver` int DEFAULT NULL,
  `idTrack` int DEFAULT NULL,
  `idManager` int DEFAULT NULL,
  `loadingInfo` json DEFAULT NULL,
  `unloadingInfo` json DEFAULT NULL,
  `applicationNumber` varchar(35) DEFAULT NULL,
  `colorTR` varchar(12) DEFAULT '#000000',
  `wasItPrinted` tinyint DEFAULT '0',
  `postTracker` varchar(20) DEFAULT NULL,
  `ownerId` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`_id`),
  UNIQUE KEY `id_UNIQUE` (`_id`),
  KEY `driverToOders_idx` (`idDriver`),
  KEY `oderToOder_idx` (`idCustomer`),
  CONSTRAINT `driverToOders` FOREIGN KEY (`idDriver`) REFERENCES `drivers` (`_id`)
) ENGINE=InnoDB AUTO_INCREMENT=45453 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

